const std=@import("std");
const P=struct{x:f64,y:f64,z:f64};const S=struct{c:P,r:f64};
fn sub(a:P,b:P)P{return .{.x=a.x-b.x,.y=a.y-b.y,.z=a.z-b.z};}fn add(a:P,b:P)P{return .{.x=a.x+b.x,.y=a.y+b.y,.z=a.z+b.z};}fn mul(a:P,k:f64)P{return .{.x=a.x*k,.y=a.y*k,.z=a.z*k};}fn dot(a:P,b:P)f64{return a.x*b.x+a.y*b.y+a.z*b.z;}fn cross(a:P,b:P)P{return .{.x=a.y*b.z-a.z*b.y,.y=a.z*b.x-a.x*b.z,.z=a.x*b.y-a.y*b.x};}fn det(a:P,b:P,c:P)f64{return dot(a,cross(b,c));}fn invalid()S{return .{.c=.{.x=0,.y=0,.z=0},.r=-1};}
fn through(p:*const [4]P,n:usize)S{if(n==1)return .{.c=p[0],.r=0};if(n==2){const c=mul(add(p[0],p[1]),0.5);const d=sub(p[0],c);return .{.c=c,.r=@sqrt(dot(d,d))};}if(n==3){const u=sub(p[1],p[0]);const v=sub(p[2],p[0]);const w=cross(u,v);const den=2*dot(w,w);if(den<1e-24)return invalid();const off=mul(add(mul(cross(v,w),dot(u,u)),mul(cross(w,u),dot(v,v))),1/den);const c=add(p[0],off);const d=sub(c,p[0]);return .{.c=c,.r=@sqrt(dot(d,d))};}const a=mul(sub(p[1],p[0]),2);const b=mul(sub(p[2],p[0]),2);const c=mul(sub(p[3],p[0]),2);const qa=dot(p[1],p[1])-dot(p[0],p[0]);const qb=dot(p[2],p[2])-dot(p[0],p[0]);const qc=dot(p[3],p[3])-dot(p[0],p[0]);const d=det(a,b,c);if(@abs(d)<1e-18)return invalid();const center=mul(add(add(mul(cross(b,c),qa),mul(cross(c,a),qb)),mul(cross(a,b),qc)),1/d);const delta=sub(center,p[0]);return .{.c=center,.r=@sqrt(dot(delta,delta))};}
fn contains(s:S,p:P)bool{if(s.r<0)return false;const d=sub(p,s.c);return dot(d,d)<=(s.r+1e-10)*(s.r+1e-10);}
fn fit(r:*const [4]P,m:usize)S{var best=invalid();var mask:usize=1;while(mask<(1<<m)):(mask+=1){var q:[4]P=undefined;var n:usize=0;for(0..m)|i|{if(mask&(1<<i)!=0){q[n]=r[i];n+=1;}}const s=through(&q,n);if(s.r<0)continue;var ok=true;for(0..m)|i|{if(!contains(s,r[i]))ok=false;}if(ok and (best.r<0 or s.r<best.r-1e-12))best=s;}return best;}
fn welzl(p:*const [8]P,n:usize,r:*[4]P,m:usize)S{if(n==0 or m==4)return fit(r,m);const s=welzl(p,n-1,r,m);if(contains(s,p[n-1]))return s;r[m]=p[n-1];return welzl(p,n-1,r,m+1);}
pub export fn smallest_enclosing_ball_3d(values:?[*]const f64,length:usize,output:?[*]f64,capacity:usize)i64{const input=values orelse return -1;if(length<4 or length>25)return -1;const raw=input[0];if(!std.math.isFinite(raw) or raw<1 or raw>8 or raw!=@floor(raw))return -1;const n:usize=@intFromFloat(raw);if(length!=1+3*n)return -1;var p:[8]P=undefined;for(0..n)|i|{p[i]=.{.x=input[1+3*i],.y=input[2+3*i],.z=input[3+3*i]};if(!std.math.isFinite(p[i].x) or !std.math.isFinite(p[i].y) or !std.math.isFinite(p[i].z) or @abs(p[i].x)>10 or @abs(p[i].y)>10 or @abs(p[i].z)>10)return -1;}for(1..n)|i|{const v=p[i];var j=i;while(j>0 and (p[j-1].x>v.x or (p[j-1].x==v.x and (p[j-1].y>v.y or (p[j-1].y==v.y and p[j-1].z>v.z))))):(j-=1){p[j]=p[j-1];}p[j]=v;}var r:[4]P=undefined;const s=welzl(&p,n,&r,0);if(s.r<0 or !std.math.isFinite(s.r))return -1;const out=output orelse return -2;if(capacity<4)return -2;out[0]=s.c.x;out[1]=s.c.y;out[2]=s.c.z;out[3]=s.r;return 4;}
